/**
 * CFI'S NOTICES and the CHIEF LAUNCH MARSHAL'S BULLETINS.
 *
 * GENERATED by tools/parse-notices.mjs from CFI_Notices.asp and CLM_Notices.asp.
 * Hand edits are fine; re-running the generator overwrites them.
 *
 * The CFI's notices were one very long page with an anchor index at the top, so
 * finding the radio frequency notice meant scrolling past eleven others. Here
 * each is its own card, newest first, searchable, opening on click.
 *
 * SAFETY-CRITICAL. These are instructions from the CFI. Do not reword them.
 */

export type NoticeLink = { label: string; href: string };

export type CfiNotice = {
  num: number;
  /** As printed on the notice, e.g. "9/09/19". Left exactly as published. */
  date: string;
  title: string;
  body: string;
  links: NoticeLink[];
};

export const cfiNotices: CfiNotice[] = [
  { num: 28, date: "9/09/19", title: "Annual Checks", body: "1. During a recent visit to the Club our insurers have asked us to tighten up on a few of our practices and so the following checks will be made when a solo pilot presents themselves for an annual check; A pilot seeking an annual check must provide the checking instructor with their total P1 flying time in a glider, over the 12-month period prior to the check. This flying time can include flights as the ‘pilot in charge’ in a two-seater glider. Also required is the total number of winch or aerotow launches undertaken as P1 over the same period. This will be checked by the instructor against the information shown in their logbook, or shown in ‘Free Flight’, to ensure that the pilot satisfies the minimum requirements of the flying card which they hold. This will be recorded and countersigned by the instructor in the pilot’s logbook or pilot’s flying card. Pilots who fail to satisfy the minimum P1 flying hours and launches stipulated in the Club Flying Card which they hold, may be downgraded by one level, which will only be reinstated when the total flight time and launches for the previous 12 months returns to the appropriate level. Any full rated instructor may reinstate a pilot’s Flying Card, however the CFI or one of his deputies must be informed of this, so that the Club’s records can be updated. 2. The weight of all pilots presenting themselves for annuals will be checked by the instructor on a set of scales which is stored in the launch point bus. This is to ensure that cockpit placard loadings are not exceeded. Should this be problematical, solo pilots who are aware of the risks which they may exposed to, by flying without a parachute, will be checked in an appropriate club two-seater training glider without having to wear a parachute, subject to the agreement of the checking instructor. For further information on annual checks refer to CFI Notice No 10 dated 14/4/12. Pilots must ensure that club single seater gliders are not flown above placard limits. Pilots who fly without a parachute must ensure that they comply with BGA Operational Guidelines; “ Parachutes – No glider shall enter cloud unless all its occupants are wearing parachutes and shall have been instructed in their use”. Private owners are reminded of the risks of flying their own gliders above placard limits. It should be noted that should an accident occur, however minor, it is possible that the insurance company could refuse to pay out, if it is found at some later date that the maximum cockpit loading had been exceeded. Remember this could apply to third party claims as well as claims for the cost of repairing or replacing a glider. Donald Mackenzie CFI", links: [] },
  { num: 27, date: "9/05/19", title: "Weights in Club Gliders", body: "In response to a recent report from an instructor, advising that when challenging a trainee who declared themselves to be within the glider’s safe weight limits, the instructor found the measured weight of P2 and parachute (using the scales in the launch bus) to be just a couple of pounds above the minimum placard loading. A dangerous situation! This check of course relied upon a set of bathroom scales which I suspect are not accurate to within 2-3 lbs. In this case the instructor correctly insisted on the glider’s extra weights being installed and briefed the trainee to ensure that this was checked on every subsequent flight. To avoid the possibility of any future reoccurrence, weights must be installed in club two-seater gliders where P2’s weight (including parachute) is less than 15kgs (33lbs) above the minimum cockpit load. Instructors are to ensure that the minimum weight in the cockpit is always 15kgs (33lbs) above the glider’s placard minimum. This ruling applies to club single seater gliders as well as club two-seater gliders. Solo pilots flying club gliders must ensure that extra weights are carried, where their weight + chute does not exceed 15kgs (33lbs) above the placard minimum. This CFI Notice replaces the weight requirement of 15lbs described in CFI’s Newsletter (July 2018). Attention is drawn to the BGA’s advice in their document ‘Managing Flying Risk’ ; “It is recommended that when an additional margin of safety is required, eg during type conversions and for inexperienced pilots, an effective cockpit load of at least 15kgs (33lbs) in excess of the placard minimum should be established , using ballast if required.” Please also note that it is the responsibility of the pilot to remove weights from the glider after their flight(s). Donald Mackenzie CFI Derbyshire & Lancashire Gliding Club", links: [] },
  { num: 26, date: "5/01/19", title: "Pre-Flight Checks", body: "The Executive Committee of the BGA has recently accepted a recommendation from the Instructors Committee to modify the BGA pre-flight check list to move 'canopy - closed, locked and doesn't open with applied pressure' to the end of the checklist. As a result, CBSIFTCBE has changed to CBSIFTBEC . The change follows a long-term analysis by the BGA of incidents and accidents related to inadequate pre-flight preparation and recognises the widespread practice of closing and locking the canopy just before launching, say in warm weather to avoid overheating and during the winter where there is a risk of canopy misting ahead of launching. The BGA pre-flight checklist which will be taught to glider pilots from 3 Jan 2019 will thus be changed to CB SIFT BEC , as follows; Controls Ballast Straps Instruments Flaps Trim Brakes Eventualities Canopy BGA publications will be updated shortly to include this change. Donald Mackenzie CFI", links: [] },
  { num: 25, date: "5/01/19", title: "Radio Frequencies", body: "Glider Radio Frequencies CAA notice CAP1606 specifies the new frequency assignments for common sporting and recreational purposes under the 8.33 kHz voice channel spacing in the UK. The switch over date from the 25 KHz channel spacing to the 8.33 KHz channel spacing on air-band radios is 3rd January 2019. All glider pilots must now use these frequencies when broadcasting messages. Dave Reedie has very kindly made the necessary changes to the radios in the club gliders. These radios and the radio which is the club's base station, have been set to operate on the new 8.33 separation standard. In addition, the stored channels in club glider radios have been set up as follows; 00 129.980 01 130.105 02 130.130 03 130.405 04 129.905 (Ground) 05 133.800 (Scottish) 06 121.500 (Emergency) Please note that 00 to 04 above replace the current gliding frequencies of 129.975 / 130.100 / 130.125 / 130.400 / 129.900. Simply put, the value 0.005 has been added to each frequency. These are as specified in CAP1606. Owners of private gliders should note this change and ensure that their radios are set up accordingly. Donald Mackenzie CFI", links: [{ label: "CAP1606", href: "http://publicapps.caa.co.uk/docs/33/CAP%201606%20833kHz%20voice%20channel%20spacing%20in%20the%20UK%20(v3).pdf" }] },
  { num: 24, date: "25/08/17", title: "Handing Over Control", body: "In view of recent events (heavy landing in Puchacz) instructors are to regularly reinforce the instruction that “I have control” means that trainees must take their hands and feet off the controls when hearing this message. Allowing trainees to continue holding onto the controls after hearing this message, is to be discouraged. If an instructor requires a trainee to continue handling the controls, say while demonstrating an exercise, he will use the standard request; “Follow through on the controls / stick / rudder / airbrakes”. Some trainees / pilots find it difficult to hear instructions when flying and should this be the case, or should an instructor find that P2 fails to respond to a “I have control” instruction, they should ‘waggle the stick’ to indicate to P2 that they wished to take back control. Trainees on sensing this ‘physical’ instruction must take their hands and feet of the controls. Instructors will demonstrate the ‘waggle the stick’ / “I have control” message to trainees, in flight, so that trainees can be made aware of the difference between this instruction and to that of flying through rough air. Donald Mackenzie CFI", links: [] },
  { num: 23, date: "15/06/15", title: "FLARM", body: "Many of you will be aware of the new instrument being fitted to the club fleet by a rolling program during the rest of 2015. That bit with all the flashing LEDs and a propensity for beeping at you. It's called Flarm . Flarm is a device to provide warnings of potential collision with other aircraft. This notice outlines policy related to familiarisation with the device and its use in club gliders. A reference document for pilots entitled “Understanding Flarm” has been placed on the members' website and can be accessed via this link. Amongst other things it describes what Flarm does, what it tells the pilot and how the information it gives should be interpreted. Pilots, including those who are already users of Flarm, are expected to be familiar with the document. At the end of the document are questions to test your knowledge of Flarm and specifications of in-flight exercises. Those yet to solo will do these tests and exercises as part of their training. Those with white cards will be allowed to fly solo in gliders equipped with Flarm once they have satisfactorily completed the tests and exercises with an instructor. Completion of the test and exercises should be signed off in the “Other Qualifications” section of personal log books. Those with red, yellow or green cards are exempt from these knowledge tests and exercises, but should be able to answer the questions correctly. Instructors have access to a briefing document via the instructors tab on Free Flight (members' admin). The Instructor Brief supplies the expected answers to the test questions and gives some further information to assist instructors on the testing and flying exercises. The Flarm display units are as shown in the Understanding Flarm document. There will be one for each seat in two-seat gliders. Each glider will have a display on/off switch. By default the Flarm unit is on when the main switch to the panel is on. The Flarm display units emit sounds when the LED displays a collision alert. The way to change the volume of these sounds is described in the Understanding Flarm document . If the unit is giving more frequent alerts than expected or liked then the display can be switched off as described in the Understanding Flarm document but please consider if that issue can be addressed by a change of your flying habit. Switching Flarm off allows you to continue in a complacently inattentive frame of mind. Flarm only functions between aircraft which are equipped. Lots of aircraft are not so equipped and the only way you will know of their presence is by LOOKOUT. Owners of private gliders without Flarm are encouraged to fit it. Finally, the one key message to stress is that if Flarm issues an alert, the FIRST ACTION must be to LOOK OUT and find the threat. Use the rules of the air to take avoiding action. Check the display only if the threat cannot be immediately seen. Peter Gray CFI", links: [{ label: "this link.", href: "https://www.dlgc.org.uk/members/misc_pages/UNDERSTANDING%20FLARM%20V6%201115.pdf" }] },
  { num: 22, date: "01/12/14", title: "Currency check flights", body: "Occasions may arise when a pilot has a successful currency check but does not manage to fly solo on the same day. Given that the check was successful said pilot may be regarded as current until the relevant expiry date. Solo flight after a check is not a requisite for currency although it is desirable, of course, that pilots fly solo and often. An instructor may decide to stipulate immediate solo flight as a conclusion to a check. e.g. For pilots known to be infrequent fliers or a marginal 'pass'. This should be clearly written in the pilot's logbook. The Free Flight logging system counts the currency days from the last flight in anything and makes no distinction between P1 or P2. It has no means of knowing if a two seat ride was a successful check or not, nor even if it was a check at all. Nor can it tell if a pilot has flown elsewhere. Accordingly it will flag up a red currency warning only for a pilot who has not flown at all at Camphill within their currency period. The warnings are just that; warnings, not diktats. If a pilot feels they are, in fact, current they should be able to prove it by showing the relevant entry in their logbook. If they 'failed' their check at Camphill they should have the integrity to point this out to the instructors and take a refresher flight even though no red warning has appeared on the screen. The on-line system is prone to intermittent failure and the warning system cannot be relied on. Tedious though it may be, all pilots should be able to produce their logbook on demand or expect to be held back. Peter Gray CFI", links: [] },
  { num: 21, date: "3/10/14", title: "Airproxes at CPH", body: "Recent conversations with a paragliding friend have highlighted an incident where he was put in fear of his life by a fixed wing glider. Other than it involved thermaling and a gaggle the precise circumstances do not need to concern us here but this was a potentially fatal air-prox of which the glider pilot may have been unaware. Flex-wing craft and fixed wing gliders are of very different handling characteristics and do not mix easily. We ought to have sufficient courtesy, let alone instincts of self-preservation, that we do not fly close enough to any aircraft so that, in the event of the unexpected, we endanger it. Endangering other aircraft is not merely stupidly suicidal but it's illegal with all the inherent consequences in respect of litigation and withdrawn insurance. Often the 'event' seems to arise suddenly and it is only in retrospect we realise we have had a lucky escape. Experience and forethought guard against being unexpectedly caught out. Experience and forethought will tell you to keep a healthy distance from other craft especially those whose behaviour may be guided by different mores to your own. DO NOT mix it with the para-gliders so closely that there is any doubt about maintaining a safe separation. We have an ever present problem in that much of Bradwell Edge is within the Camphill traffic zones as defined by the 1:500,000 CAA VFR chart and we know that for a fixed wing, training operation that zone is only just big enough. We must share it (some of the time) with the flexwing community. Inevitably there will be conflicts and resentment, on both sides, which must be sorted on the ground, NOT in the air. If you feel the flexwing pilots have behaved unreasonably give me chapter and verse and I will put it to them. For your part you must behave in an exemplary fashion. Two blacks don't make a white. Peter Gray CFI", links: [] },
  { num: 20, date: "17/09/14", title: "Landing skills (or lack thereof)", body: "The ability to spot land is a vital skill that really comes into play during an out landing in a field or at a different airfield. Learning the skill at Camphill is somewhat hampered by our having no runways; we can land more or less anywhere and who minds if the final resting place comes as a mild surprise? We also tend to get lazy and habituated, quite often to the disadvantage of others. Signs of inability or laziness are evidenced by Landing in front of launch, especially in Westerlies. Aiming at windsock regardless of the wind direction. Rolling over cables when the glider has a tail skid rather than a wheel. Habitually in the same place. Always strangely long. Can’t follow a brief for an specific landing spot. Cannot control the length of ground run, especially cannot extend it. Obviously, when learning, things go awry and use of visible landing markers can be a great help but once trained a pilot should be capable of accurate landing all the time. The instructors at Camphill will increasingly be paying attention to pilots who display the above characteristics. On check flights landing skills will be assessed along with everything else and a takeover may be expected if pilots set up a final to obstruct the launch runs, aim unnecessarily at the windsock or miss the briefed spot. On check flights an instructor takeover is regarded as a fail requiring further tuition in two seaters. Even when there is no \"fail\" instructors may recommend further training. Peter Gray CFI", links: [] },
  { num: 19, date: "04/07/14", title: "Simulator Demonstrator Rating", body: "As a member of the Derbyshire and Lancashire Gliding Club you will no doubt be aware of our excellent pilot training aid; the simulator. Used as a supplement to our traditional methods of training, the simulator is a serious training instrument that can also be an entertaining piece of equipment for our visitors or when used for more fun orientated tasks, such as wet day competitions. Whatever the purpose we need to remember it is a relatively expensive piece of kit so one, at least, amongst the users needs to have been trained on the basic functions and care of the hardware. The lamps for the projectors are in the order of £70.00 each and the computer has its own running costs, therefore usage is charged and the log needs to be filled in. With regard to teaching pilots nobody who is not an instructor may give formal instruction. An instructor has been trained to teach to a syllabus with standardised phraseology and methods; the ambition being for the pupil to receive coherent tuition no matter who gives it. In our interactions with actual or potential pilots there is an hierarchical structure with instructors of varying seniority through the Passenger Carrier to the ordinary club member. The Passenger Carrier is a qualified pilot who is permitted to take people for a (strictly) non-instructional flight. Our local rule is that they receive the same training in airmanship and passenger care as a basic instructor but they may not allow the passenger to handle the controls. An upgraded version of the Passenger Carrier is what is heralded as replacing the BI under EASA's rule next year. In addition we have introduced, specific to Camphill a qualification that we call a Simulator Demonstrator. The principle objective is to allow non-instructors to entertain visitors on the simulator and, providing certain criteria are met, is a rating any member can apply for. It will allow them to demonstrate the basic effects of the controls, flight planning pertaining to the simulator along with initial introduction to a glider. The emphasis is on 'demonstrate'; it is not an instructor rating and a demonstrator may not offer any form of instruction to a pilot. On the grounds that some of these simulator demonstrators will progress up the instructing ladder and that some of the visitors will progress through a real flight to learning to fly we think it important that the consistency of approach and phraseology used by instructors should start in the simulator. To that end, using the EASA flight training syllabus and the BGA instructor manual we are formalising the training for our Simulator Demonstrator and Passenger Carrier so that the format is not dissimilar to the Flight Instructor training from the BGA. Therefore anyone starting at any level will receive the same basic training in passenger care, safety awareness and phraseology that accompanies the basic use of controls. This won't be time wasted, as the Demonstrator moving on to become a Flight Instructor will already know and be familiar with the basics. The Demonstrator rating (Camphill Simulator Demonstrator Rating to give it the full title) is described on the members' website at http://www.dlgc.org.uk/members/SimulDemstrtr.asp . There is the syllabus, a record of training similar to what you will use if you go for a higher rating and an assessment form to record a qualifying test. The outcomes and new status will be recorded in the files that we keep for each of our pilots. Hopefully this will open up to lots of our pilots the opportunity for rewarding interaction with our guests, potential members and each other. If you are interested in a rating then talk to myself, John McKenzie, Dave Martin or Brian Allen. Peter Gray CFI", links: [{ label: "http://www.dlgc.org.uk/members/SimulDemstrtr.asp", href: "http://www.dlgc.org.uk/members/SimulDemstrtr.asp" }] },
  { num: 18, date: "29/11/13", title: "Club Level Incident Recording", body: "Introduction This is to describe and explain a new system for keeping records about incidents. Under EASA regulations, those BGA clubs undertaking training as part of the BGA Approved Training Organisation (ATO) must comply with a BGA Safety Management System which requires the collection and review of information about accidents and incidents within clubs. To paraphrase the existing official definitions in Laws & rules section 13, an accident is described as a (flying related) event that causes significant damage to a glider or person. An incident is an event, or it can be an ongoing situation, associated with the operation of aircraft, which affects or could affect the safety of operation without amounting to an accident but, even so, may result in minor damage or trivial injury. To comply with the new requirements the BGA is clarifying it’s definitions such that an accident is any occurrence resulting in injury or damage occasioned in flight or on the ground. An incident is an unusual event which takes place in connection with the aviation activities of the club, but with no injury to persons and no damage to aircraft or property. The scope of incidents will be expanded to recognise some which may not be deemed serious or do not have immediate implications outside the club; these may be regarded as club level incidents (CLI) There is no lower level of severity to define what is to be treated as a CLI other than if, in the opinion of any pilot, the event ought not to have occurred then it can, and should, be treated as a CLI. It has been decided that DLGC will, with respect to an incident: a. Interpret as serious to mean there was a probability of an accident, b. Decide if there are safety implications beyond the club. Incidents that are rated in either of the categories above will be submitted to the BGA using the reporting methods already in use. Other incidents will be seen as CLIs and will not be individually reported to the BGA but there will to be a requirement to submit an annual review of all accidents and incidents. All clubs operating as part of the BGA ATO will be subject to random audit by the BGA, or the CAA to whom the BGA is answerable. The Club’s existing safety log system lends itself to the collection of data so there will be minimal change for the general membership. Relationship to Safety Lessons Log The Safety Lessons Log (SLL) will continue to be added to and published in it’s current form – i.e. the SLL will continue to include reports and lessons learned from any level of incident or accident. SLL items will continue to be anonymised. Information Collection Pilots are expected to submit incident reports on anything they feel should not have happened. A continuing situation may be regarded as an incident. The method of reporting will be By note (optionally enveloped) into the locked payment boxes on the launch point vehicle and in the Clubhouse, OR By email to the CFI, a DCFI, the Safety Officer or the Chairman. The information in CLI reports will be confidential. The details of CLI s will be known only to the CFI, a DCFI, the Safety Officer or the Chairman except that any reports submitted on paper and not enveloped will be seen by the office administrator. Details required are: The date the event occurred or the situation was discovered. Details of the event or situation. This means the facts of what has been observed or discovered, including the name(s) of any person/people involved. Opinions or suggestions are NOT wanted. Name of reporter. Information Processing Reports of incidents will be entered into a recording system which will be accessible only to the CFI, DCFI’s and Safety Officer. attribute characteristics (e.g. type) to incidents. enable incidents to be analysed for characteristics, frequency, trend and member involvement. record a description of any consequent action(s) decided upon and a date of completion of the action(s). NOTE : the intention is to comply with a BGA template for CLI records – which may or may not match the specification in b, c and d above. Actions on CLI’s The records of CLIs will be reviewed from time to time by the CFI, DCFIs and Safety Officer, the purpose such review will be to: decide upon any actions to be taken on new CLI reports follow up on the completion of actions previously decided upon recognise emerging trends in the data Peter Gray CFI", links: [] },
  { num: 17, date: "31/10/13", title: "Cable release checks", body: "We are going to change one of our ancient rituals. The cable release checks that must precede the first flight of the day are currently done at the launch point. So much more sensible it would be to include the check as part of the DI down at the hangar or trailer park. So from now that's what we will do. The downside is that we need to break the habit of a lifetime and that will fail periodically until we get into the swing of it. If we all make a joint effort with the club gliders it will help cascade the change amongst the private owners. The DIer will try to remember to do it. The early morning Greek chorus outside the hangar will remind the DIer. The chorus will identify a player who will assist the DIer with a weak link strop. The chorus, when at the launch point, will remind the launch marshal to remind the hooker on to remind the pilots that the check should have been done already. The chorus will hoot in derision should the pilots have forgotten. Thus we might all learn to do it before going up the field. This change will bring all the elements of the daily inspection into one session to ensure any glider deemed serviceable by a signature in the DI book may be removed to the launch point as fit to fly. I suggest that until we become accustomed to this change we add RC to the PCC in the DI book. Don't forget the test should be done with a set of serviceable rings which might give the private owners a temporary problem. It is important they realise the prompt at the launch point will diminish over time and like remembering to connect their elevator it will be down to them to ensure the check and regard it as part of their DI. You should recall that the DI procedure is derived from the BGA's generic schedule supplemented by the manufacturer's recommendations and any of your own requirements. Checking the release, including the back release, is in the generic schedule already. Peter Gray CFI", links: [] },
  { num: 16, date: "5/7/13", title: "Independent secondary rigging checks", body: "For as long as I can remember it has been the normal practise at Camphill to follow the BGA recommended practice of following the rigging of club aircraft with a secondary, independent check of the control connections. It has also been our practise that this will be followed by a DI before the glider flies next and all our DIs now are followed by a positive control check. While our current pilot’s manual makes the performance of a DI with positive control check a requirement for all gliders at Camphill, the question of secondary rigging checks has been neglected. This notice is rectify that and establish our normal practice as a rule which reads -. After the rigging of any club glider a suitably qualified independent person will conduct a secondary check of the rig. The glider will have the normal DI and positive control check before it next flies. The pilot’s manual section on preparation for flight will be amended at the next revision with the above rule which applies forthwith. Pilots rigging gliders with automatic connecting controls may feel there is no need to do a positive. Assembling some tailplanes nominally automatically connects the elevator but the elevator connection can be mis-positioned yet allow the tailplane to bolt home normally. The positive check is intended to be an ingrained procedure that no pilot neglects during a pre-flight inspection. The mind-set that says “I don’t always have to do it” is dangerous. Whatever method is used to check the integrity of automatically connected controls is unimportant, it should be done and signed in the DI book. Peter Gray CFI", links: [] },
  { num: 15, date: "3/5/13", title: "Club third party insurance", body: "Ref. CFI’s notice number 12. 4th December 2012 Club third party insurance Since we announced the guidance for non-instructors to fly passengers or mates in the two seaters I have been asked about the insurance position. Our insurance broker has given me a jargon free explanation and it goes like this. \"I confirm the position regarding passenger/third party liability under the club's glider fleet policy. This is covered by section IV of the policy whereby liability cover is provided in respect of any person whether they are purely a passenger or regarded as a second pilot (i.e. mutual flying). Should an incident occur which results in an injury to a passenger or second pilot the insurance will pay a maximum of £2,000,000 in any one claim. If a further third party was involved (i.e. someone not in the glider) the payment would be divided between the two parties and if property was damaged at the same time then the two million could be split three ways.\" The P1 (who must be declared before the flight starts) is responsible for his own insurance against injury as is the case for all pilots acting as pilot in command. Whilst it may be irksome to have to declare the P1 to the duty clerk and ensure it is recorded when mutual flying, believe me, it can save a lot of lawyers fees which leaves more for the pay-out. P B Gray CFI", links: [] },
  { num: 14, date: "22/3/13", title: "Performance of Daily Inspections", body: "As of 25th March 2013 any Camphill pilot may perform a DI on a Club glider without supervision providing they have been trained. The training will be type specific, recorded in their log-book, their training record, their Camphill card and their name must be entered in the Club’s database of pilots so approved. Camphill pilots with a share in their own glider but who do not hold a LAPL(S), SPL or BGA bronze badge with XCE must be similarly trained. Historically the authority to do a DI has been within the purlieu of the club and consequent on the training given to pilots at any appropriate stage of their progress. Two years ago it was perceived within the gliding world that EASA had determined the inspection to be an act of pilot/owner maintenance to do which the person had to be qualified. Qualification was deemed to be the forthcoming LAPL(S) or, in the interim, the BGA bronze badge. Accordingly we changed our procedures such that a pre-bronze pilot might only do a DI under direct supervision of an instructor. This interpretation is no longer held to be correct. Note the following points distilled from Laws & Rules, Part M of EC regulation No. 2042/2003, section A, subsection 301 and BGA briefing on Airworthiness & Maintenance Management (Feb 2013). It is a EASA requirement that a pre-flight inspection is performed before the first flight of the day. The BGA requires that a DI is performed on BGA gliders which may suffice for all the subsequent flights that day. A DI or PF is not an act of maintenance so does not require a release to service note to provide which the individual would need some recognised authority. In the case of permitted pilot/owner maintenance – a pilot licence. Whoever does a DI or PF on a BGA glider is expected to be competent on the type and the inspection has to be to the requirements of the BGA’s generic Glider Maintenance Schedule AND any additional ones in the aircraft manufacturer’s manual. It appears that any person with a pilot’s licence is deemed, ipso facto, to be competent to do a DI or PF on the type specified in their rating. For BGA club aircraft the DI may be performed by any person without a licence at the discretion of the club management. Private owners who do not have a licence are advised to seek the assistance of a qualified syndicate partner or person approved by the club. The ‘discretion of the club management’ means that we can allow any pilot to do a DI provided that they have been trained to the schedule for the type they will inspect, that the training is recorded and the club hold a record of authorised personnel. Our requirement for trained pre-licence pilots to be supervised in the DI no longer appertains but no person who does not have type specific training recorded and with an endorsement on their Camphill card may DI a glider unsupervised. By way of reminder the DI includes not only determining if bits are damaged or not functioning but ensuring the ARC is valid, the insurance extant, that the required documents are aboard and there are no outstanding deficiencies recorded that should be rectified before the next flight. For BGA gliders the DI book is the recommended place to record things. The current issue of DI book has a guide to generic tasks at the front and may be customised to comply with the manufacturer’s recommendations as to pre-flight inspections. Ignore the bit that says you need a licence to do a DI. This notice supercedes CFI’s notice No 4 of 26/4/11 Peter Gray CFI", links: [] },
  { num: 13, date: "", title: "Call-sign for Camphill", body: "CFI’s notice 7/1/13 No. 13 Call-sign for Camphill Up to now we have used 'Camphill ground' as the call sign for traffic around Camphill to contact the crew at the launch point. The CAA have decided that the suffix 'ground' should be reserved for the ground handling operations at airports with ATC so it become inappropriate to use it elsewhere. In future we will use 'Camphill Base' as the call sign for our airfield. All pilots please note this and help each other to shed the habit of years and adopt the new convention. P B Gray CFI", links: [] },
  { num: 12, date: "", title: "Guidance for Pilots wishing to fly two seat gliders at Camphill", body: "CFI's notice 4/12/12 number twelve Guidance for Pilots wishing to fly two seat gliders at Camphill Other than solo there are three categories of two seater flying; instructional, passenger carrying and mutual. At Camphill the yellow card and 100hrs P1 on gliders is the minimum competence level required for training to be pilot in charge in any category. The LAPL(S) on its own is not necessarily indicative of adequate Camphill specific skills. For non-instructors a passenger carrying rating is available that meets BGA requirements. Passenger carrying rating · The pilot will require training by the CFI or a Deputy CFI or a BI coach up to the Basic Instructor level of airmanship. i.e. There will be no training in flying instruction but otherwise the tuition will follow the syllabus for BI training. · A rating to fly passengers will only be granted by the CFI. · The rating may only be exercised by right at Camphill. · The passenger carrying rating will be annually renewable by the CFI or a DCFI which may substitute for the ordinary annual checks and will follow the same system of timing. · The minimum currency requirement for renewal is 20 hours and 30 launches as PIC (Pilot in Command, solo or dual) in the preceding twelve months. · The medical requirements are a NPPL declaration to DVLA 2 standard up to January 2014 or a LAPL(S) medical. Instructional · An instructor may fly a two seater as pilot in command under the privileges of and within the limits of their rating. Visiting instructors will require the approval of the CFI, a DCFI or senior instructor specifically approved by the CFI. Mutual flying · Mutual flying describes two pilots sharing a non-instructional flight in a two seat glider. · The P1 must have a Camphill issued passenger carrying rating as a minimum qualification. · The pilot declared as P1 will normally sit in the front seat and do the take-off and landing. An instructor acting as P1 may elect to sit in the back. · Permission to utilise a club glider must be sought from any duty instructor of the day. Passenger carrying · Describes the carriage of passengers who are friends or family of a club member, who have been made temporary members and who are not required to pay for the flight. · The pilot must have a Camphill issued passenger carrying rating as a minimum qualification. · The passenger will not handle the controls at any time. · The pilot will normally sit in the front seat though pilots familiar with flying a particular glider from the rear seat may elect to sit in the back. Any glider with limited panel (or controls) in the back should be flown from the front under all circumstance. · The conditions criteria will be based on those for a trial lesson. A full rated instructor or de-restricted Flight Instructor assessing the conditions will apply the same judgements as he/she would for a trial lesson. A Basic instructor or passenger carrier will abide by the BGA weather minima, seeking advice where appropriate. · All pilots must indicate their intentions to do the flight to a duty instructor. If the flight is to be in a club’ machine agreement to utilise the glider must be sought from any duty instructor of the day. A basic instructor or passenger carrier will obtain a briefing from the senior duty instructor. Solo flying in club two seater gliders · Both the K13 and the Puchacz are used for training and the pupil will solo in which ever he or she finally proved their competence on the great day. · Conversion to the Ka8 will require flights in the K13 and some may be solo at the instructor’s discretion. · Instructors subsequently may see it appropriate to allow solo flight in a two-seater after a series of training flights, because of time constraints or lack of single seat gliders. · Otherwise solo use of the two-seaters initiated by non-instructors may only take place with the specific approval of the duty instructor. · The pilots must be manifestly competent on type which rests on the instructor’s judgment. · The conditions should be well within the pilot’s known competencies. · Flights will be conducted within the privileges of the pilot’s card colour. · The flight time should be limited by the duty instructor to ensure appropriate availability of the glider, with a maximum of two hours. Peter Gray CFI", links: [] },
  { num: 11, date: "", title: "Policy for the use of the K18", body: "CFI's notice 15/8/12 number eleven Policy for the use of the K18 Use of the K18 has historically been limited to experienced pilots on the basis that it is a rare and rather nice glider. It is not a difficult glider to fly and as part of the club fleet use should not be restricted on the grounds of rarity but only by reason of a pilot’s incapacity to fly it safely. No pilot should be allowed to fly any glider if their mentors consider them unable to reliably fly it safely in the prevailing conditions. In respect of general flying, once a pilot is off daily checks they may be converted from the K8 to the K18. The white card parameters for conversion to red card are good indicators of required competency. The K18 is the glider likely to be used for badge attempts and serious soaring. As such it may be away for prolonged periods. A pilot declaring a badge attempt or cross country goal may have unlimited use of the machine for that episode. For occasional local soaring the glider should be returned to site after a maximum of two hours flying. Peter Gray CFI", links: [] },
  { num: 10, date: "", title: "Annual check flights", body: "CFI's notice 14/4/12 number ten Annual check flights All non-instructor solo pilots must undertake annual check flights with an Assistant or Full rated instructor. To be allowed to fly solo pilots must satisfactorily complete the check flights no more than 12 months after the previous completion date. A pilot’s first due date will be twelve months after that on which they were signed off daily checks. If during the twelve months preceding their due date pilots have - . Passed the final test flights for transfer from the white card to the red or the yellow card to the green. Passed the general skills test flights required to obtain a Bronze badge. Then they may adopt the date of completion of those events as their annual check flight due date. Pilots completing their checks, for whatever reason, by up to two months before the due date may defer the next check to twelve months from that due date. Instructors have a separate system of checks. The checks will require at least two flights. This will involve demonstrating satisfactory handling of the following. Winch launch, correct lift-off and rotation with lay-off. General flying - scan cycle lookout, trimming, speed control & co-ordination. A circuit starting plus or minus 200ft on normal HKA, including correct lookout. Final turn & approach. Stalls & reduced g or spins & spiral dive. Simulated launch failure with correct recovery. As with any check flight the pilot may benefit by trying additional exercises for training and/or personal satisfaction but the ones listed above will be in the nature of a test not tuition. Instructors additionally may include topics relating to national or local safety campaigns or changes in recommended practise. Persistent failure of check flights (or any other problem) entailing a period of re-training will be accompanied by demotion to a lower card . In addition, to retain their annual check status pilots holding green cards or yellow cards will be required to fly, between annual checks, at least 15 hours and 15 winch launches and pilots holding red cards, at least 5 hours and 15 winch launches. Power flying hours can count up to 5 hours. Those who have not met these currency conditions will be rated at the next lower card colour until their currency in the previous 12 months returns to the levels above. If a pilot is in any doubt about his/her currency then a check flight should be undertaken. Peter Gray CFI The text of this notice is an amendment to the pilot’s manual and the advice on the website will be a copy. With any luck there will only be one version of the advice on annual checks in existence.", links: [] },
  { num: 9, date: "", title: "XCE requirements for ‘local soaring’", body: "CFI's notice 9/3/12 number nine XCE requirements for ‘local soaring’ Flying above cloud in wave or convergence lift and soaring the local edges below the minimum circuit height for the day both predispose to an out-landing for which the pilot must be trained and qualified. It is therefore a club requirement that pilots must hold the BGA cross country endorsement to the bronze badge (XCE) before engaging in the above activities. [It is anticipated that in future this qualification will equate to the European LAPL(s) and SPL.] For now, notwithstanding pending changes, red card pilots should regard their limitation on soaring only lifted when they have the Bronze and XCE Yellow Card pilots should regard their limitations as increased to preclude soaring above cloud-base or below circuit height until they gain their XCE. Peter Gray CFI", links: [] },
  { num: 8, date: "", title: "Risk of collision with launch cables", body: "CFI's notice 13/9/11 number eight Risk of collision with launch cables Recent reports of hill soaring gliders encroaching on the winch area prompts me to reiterate one of our more important survival strategies. DO NOT overfly the airfield at less then a very generous winch launch height unless the winch tow out vehicle is crossing the field. In particular, when hill soaring reverse your beat well in advance to avoid the launch, bearing in mind that a launch failure may result in unpredictable behaviour by the launched glider. You need to be particularly self disciplined when the winches are at the bowl because this is where the glider follows a path which is much of the time virtually along the hill soaring beat and often when the only soarable part of the hill is over the bowl. Unhappily there is local precedent for dying after colliding with the cables and the fact that reports are reaching me of heart stopping moments in this respect suggests that we are becoming a little cavalier about it. Launch marshals should be very reluctant to launch a glider to the south-west when soaring gliders are tracking south along Durham edge. Peter Gray CFI", links: [] },
  { num: 7, date: "", title: "Canopy damage", body: "CFI's notice 23/7/11 number seven Canopy damage The cracks in our canopies are an absolute disgrace and they nearly all originate from around the DV panel. There is an old gliding adage that 'Hasty pilots and bulky sleeves break canopies'. Patently we have a membership amongst whom some are unaware of that caution so lest there be any further doubt let us move from adage to diktat. The only reason you reach through the DV panel from outside is to access the canopy release catch and you only do it when the glider is stationary. You open the canopy by grasping the release or accessible frame-work or dedicated handle, not anything made of perspex. Only then are you free to do whatever you need in the cockpit There are no exceptions. In case you might entertain any lingering doubt about this principle please read the following paragraphs very carefully. The only reason you reach through the DV panel from outside is to access the canopy release catch and you only do it when the glider is stationary. You open the canopy by grasping the release or accessible frame-work or dedicated handle, not anything made of perspex. Only then are you free to do whatever you need in the cockpit Peter Gray CFI", links: [] },
  { num: 6, date: "", title: "BGA Notice 2", body: "CFI's notice 4/7/11 number six Another from the BGA \"We have been advised that a Red Arrows display at Goodwood was delayed on 30th June because of gliders in the display area. The BGA Airspace Committee has asked in the strongest terms that CFI's reinforce the need for all pilots to ensure that they check for airspace restrictions and other airspace warnings prior to getting airborne. There is no excuse for ignorance. The CAA usually prosecute pilots who infringe restricted airspace. Details of known RA(T)s are available at http://www.gliding.co.uk/bgainfo/airspace/rats.php NOTAMs are of course the primary source of information.\" Please read this BGA circular . Peter Gray", links: [{ label: "http://www.gliding.co.uk/bgainfo/airspace/rats.php", href: "http://www.gliding.co.uk/bgainfo/airspace/rats.php" }, { label: "this BGA circular", href: "https://www.dlgc.org.uk/members/airspace/Airspace%20Safety%20-%20RA(T)s.pdf" }] },
  { num: 5, date: "", title: "BGA Notice 1", body: "CFI's notice 4/7/11 number five This is fresh from the BGA. \"Since October 2010 there have been 11 cases of gliders being flown in an unsafe condition arising from incorrect or incomplete rigging, the presence of loose articles, unlocked airbrakes that sucked open during the launch, or unlocked canopies that detached in flight. It is fortunate that no-one has been killed or seriously injured. Accidents of this kind can be avoided if: 1) rigging is directed by a person experienced on the type, in accordance with the flight manual, and without interruption or distraction; general advice on rigging can be found in the BGA instructors? manual 2) DIs are conducted by a person experienced on the type, without interruption or distraction 3) the pilot carries out proper pre-flight checks, again without interruption or distraction Please do whatever you can individually and in your club to stop the current spate of these completely avoidable and potentially lethal incidents and accidents.\" You could go to http://www.gliding.co.uk/bgainfo/safety/documents/rigging.pdf to see the BGA have been on at this one since 2006 and still we have a steady run of stupid mistakes. Take a vow of silence and keep your mates safe. You might even hear the skylark ascending and the curlew calling for a change. (pun intended) Peter Gray", links: [{ label: "http://www.gliding.co.uk/bgainfo/safety/documents/rigging.pd", href: "http://www.gliding.co.uk/bgainfo/safety/documents/rigging.pdf" }] },
  { num: 4, date: "", title: "DI Policy", body: "CFI's notice 21/4/11 number four SUPERCEDED ON 23/3/13 BY CFI's NOTICE No.14 The question of who may DI a glider causes some current anxiety. It will become the law that to do the maintenance tasks on an aircraft that are approved as 'pilot/owner permitted maintenance' a glider pilot must be qualified. Qualified as a glider pilot that is, i.e. has a glider pilot's licence. Licences and all the procedures that go with acquiring one will be mandatory from 2012 as far as EASA are concerned but for gliding in the UK a phased approach is anticipated with 2015 as the final deadline. The DI is seen as an act of maintenance by the law makers and must be recorded as such which makes the DI book an indispensable document and it requires the signature of the qualified person. The parameters of the glider pilot's licence are to be essentially those of the BGA bronze standard so to get us in the right frame of mind the BGA have decreed that only a pilot with bronze badge may do 'pilot/owner maintenance' even now. Thus we have the current situation whereby pre-bronze pilots are forbidden to DI their gliders. This on the face of it does not allow for training to perform DIs and it is illogical to leave a pilot thus untrained until he or she gains a licence which permits them to do it. To cut this Gordian knot I have clarified our position with the following policy statement. \"Pilots under training for the glider pilot licence (pre bronze level) may be taught to DI type specified club gliders and maintain their skill by doing the inspections. Until licensed they shall be supervised by a full or assistant category instructor who will countersign the pupil's entry in the DI book\" . Tasking the instructor with the supervision reflects that this is a training matter. Private syndicates with a pre-bronze member will need to make their own arrangements to ensure the DI is signed off only by a qualified pilot familiar with the type. Like it or not the Bronze soon will be no longer optional which has implications for some established members if they wish to escape daily briefings, constant supervision and a permanent pupil status. It is not clear to me at this time whether the licence will require an equivalent to the cross country endorsement. It would seem logical that it should. Peter Gray", links: [] },
  { num: 3, date: "", title: "Rudder Usage", body: "CFI's notice 21/4/11 number three Handling skills are an essential pre-requisite to successful piloting and never more so than during slow flight when the angle of attack is high. The classic spin off a final turn, often fatal and always painful, is the consequence of a stall from allowing the speed to decay and yaw from abuse of the rudder. Abuse in this context means applying too much for the amount of aileron used. Excess rudder makes the nose travel in the desired direction which mimics the turn and is a comforting visual illusion to a pilot desperate to get his craft pointing at the landing area. If you need further explanation of the dynamics talk to an instructor. Soon. Primacy is the description given by psychologists of the fact that things you first learn get imprinted the deepest and will surface in moments of stress to supercede things learned subsequently. Your mother would have said \"old habits die hard\". Along with lookout I intend that accurate handling is developed as a prime skill to which end and with regard to spin avoidance in particular we are going to adopt a zero tolerance approach to the over ruddered turn. This is summarised by \"Any tendency by a pupil to over rudder turns will be corrected. Any such tendency will preclude the first solo and will fail any pilot's check flight\" . Peter Gray", links: [] },
  { num: 2, date: "", title: "ABCD", body: "CFI's notice 21/4/11 number two Further to the previous notice and continuing the theme of diligence over the airworthiness of your aircraft we aim to extend our normal practise of checking the control sense and removing the rudder lock before climbing in, by adopting the BGA's ABCD mnemonic. It is in the same spirit as the power pilot's 'walk round'. When you approach the 'plane you intend to fly you look at it critically . You may just spot something wrong like a pitot cover still on or a flat tyre or (and its true) the tailplane missing. A is for Airframe which includes the rudder lock B is for ballast which may be inaccessible once you're in C is for controls working the right way D is for dolly - not good for your C of G. Not onerous, something we can share at the launch point with good humour but yet an important start to the focussed mindset that a pilot needs. Peter Gray", links: [] },
  { num: 1, date: "", title: "Distraction", body: "CFI's notice 21/4/11 One of the significant activities where there has been a number of incidents over the last year, most of which should have resulted in a fatality but only one did, is the rigging and inspection of gliders before flight. Haste and distraction are major causes of incomplete preparation for anything let alone flight so I'm announcing a zero tolerance attitude to chattering away at pilots who are rigging, DI-ing or doing their cockpit checks. It reads like this - \"Pilots engaged in rigging or performing a DI or their cockpit checks will not be engaged in conversation\" . The principle's not new but it is time it became so engrained in our culture that such restraint is second nature. Don't leave it to the instructors to do the admonishing because learning a group discipline is a mutual effort. Have a dig at the instructors if they deserve it and be altogether uninhibited about telling somebody to go away whilst you are busy. It's pretty distracting being surrounded by gossiping gas-bags even when the conversation is not directed at you specifically. I hesitate to suggest we all take a Trappist vow of silence airside but if the golfing fraternity can demand silence within sixty feet of the player I think a pilot, trying to focus his mind, deserves similar consideration. Peter Gray", links: [] },
];

